def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    if n == -1:
        records = self.output_queue
    else:
        records = self.output_queue[:n]

    if qid != -1:
        records = [record for record in records if record.qid == qid]

    for record in records:
        if dehydration_hooks:
            self.output_queue.remove(record)
            if dehydration_hooks.get(record.__class__, None):
                record dehydration_hooks[record.__class__](record.value)
        if hydration_hooks:
            if hydration_hooks.get(record.__class__, None):
                hydration_hooks[record.__class__](record.value)

    for handler in handlers:
        handler(record)
