def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    corrected_cmd = []
    for item in cmd:
        if item.startswith('#!'):
            try:
                # Remove shebang for deep-path shebangs
                item = item.split('#!')[1].strip()
                corrected_cmd.append('#!' + item)
