def lru_cache(maxsize=128, typed=False):
    """
   Decorator to wrap a function with a memoizing callable that saves up to `maxsize`
    results based on a Least Recently Used (LRU) algorithm.

    Parameters:
        maxsize (int): Maximum size of the cache.
        typed (bool): If True, only call `func` when exact type matched.

    Returns:
        callable: A memoizing callable wrapped around `func`.
    """

    def memoize(func):
        cache = {}

        def wrapper(*args):
            if typed:
                key = (func, args)
            else:
                key = args

            if key in cache:
                return cache[key]
            else:
                result = func(*args)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

        return wrapper

    return memoize
```

