        self.cache = {}
        self.usage_count = {}
        self.min_increase = 1
        self.typed = typed

        if maxsize > 0:
            self.allocation_optimization = self.LFUCacheAllocationOptimization(maxsize)

    def LFUCacheAllocationOptimization(self, maxsize):
        # Optimized for allocation strategies if required
        # This could involve a move-to-front strategy or other memory-efficient techniques
        pass

    def get(self, key):
        if key in self.cache:
            self.increment_usage_count(key)
            return self.cache[key]
        else:
            return -1

    def set(self, key, value):
        if len(self.cache) == self.maxsize and self.min_increase == 1:
            self.min_increase = self.lfu_decrement_usage_count()

        if self.typed:
            key = key.encode('utf-8')

        if key in self.cache:
            self.cache[key] = value
            self.increment_usage_count(key)
        else:
            self.cache[key] = value
            self.add_to_cache(key)

    def increment_usage_count(self, key):
        current_count = self.usage_count.get(key, 0) + 1
        self.usage_count[key] = current_count
        self.update_min_increase(current_count)

    def lfu_decrement_usage_count(self):
        min_count = float('inf')
        min_key = None
        for key, count in self.usage_count.items():
            if count < min_count:
                min_count = count
                min_key = key
        if min_key is not None:
            self.usage_count[min_key] -= 1
        return min_count

    def add_to_cache(self, key):
        if len(self.cache) == self.maxsize:
            self.cache.pop(self.get_min_key())
            if key in self.cache:
                self.increment_usage_count(key)
        self.cache[key] = None  # Empty entry to mark the cache position

    def get_min_key(self):
        min_key = min(self.cache, key=self.cache.get)
        return min_key
