from typing import List

def integral(bins: List[float], edges: List[float]) -> List[float]:
    # Check if inputs are valid
    if not all(isinstance(x, (int, float)) for x in bins):
        raise ValueError("Bins values must be numeric.")
    if not all(isinstance(x, (int, float)) for x in edges):
        raise ValueError("Edges values must be numeric.")
    if not len(bins) == len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")

    # Compute integral
    integral_values = []
    for i in range(len(bins)):
        integral_values.append((edges[i + 1] - edges[i]) * bins[i])

    return integral_values
