def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    try:
        for observer_field, response_value in observer_schema.items():
            if observer_field not in last_applied_manifest:
                last_applied_manifest[observer_field] = response_value
            elif isinstance(response_value, dict) and isinstance(last_applied_manifest[observer_field], dict):
                last_applied_manifest[observer_field] = update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[observer_field], observer_schema[observer_field], response_value
                )
            elif isinstance(response_value, list) and isinstance(last_applied_manifest[observer_field], list):
                last_applied_manifest[observer_field] = update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[observer_field], observer_schema[observer_field], response_value
                )
            else:
                if response_value != last_applied_manifest[observer_field]:
                    last_applied_manifest[observer_field] = response_value
    except KeyError as e:
        raise KeyError(f"Could not update last_applied_manifest because {e}") from e
