def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")

    if not isinstance(params, (dict, list)):
        raise TypeError("params must be a dict or list")

    if self.SQLParams.in_style == SQLParamStyle.NAMED:
        if not isinstance(params, dict):
            raise TypeError("params must be a dict when SQLParams.in_style is named")
    elif self.SQLParams.in_style == SQLParamStyle.ORIGINAL:
        if not isinstance(params, list):
            raise TypeError("params must be a list when SQLParams.in_style is ordinal")

    # Convert in-style parameters to out-style parameters
    if isinstance(params, dict):
        out_params = {k: str(v) for k, v in params.items()}
    elif isinstance(params, list):
        out_params = [str(v) for v in params]

    # Format the SQL query with the out-style parameters
    formatted_sql = sql.replace("?{%s}" % self.SQLParams.in_style, "%s")
    formatted_sql = formatted_sql.replace("?", "?{%s}" % self.SQLParams.in_style)

    return formatted_sql, out_params
