def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise ValueError("Invalid input types")

    if number < 0:
        raise ValueError("Input number cannot be negative")

    if padding is not None and (padding < len(alphabet) or padding > len(str(number)) + 1):
        raise ValueError("Padding is out of range")

    result = []
    while number > 0:
        if padding is not None:
            result.append(alphabet.number_to_index(number % len(alphabet)))
        else:
            result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        result = result[:padding]
        if len(result) < padding:
            result.extend([0] * (padding - len(result)))

    return ''.join(alphabet.index_to_number(r) for r in result[::-1])
