def parse_frequency(frequency):
    if not frequency:
        return None
    if frequency == "always":
        return None
    if not frequency.isnumeric():
        raise ValueError("Invalid frequency format")
    spec = frequency[-4:-1]
    value = int(frequency[:-4])
