        else:
            scale = self._counts[self._n-1] / other
            self._counts = {i: self._counts[i] / scale for i in range(self._n)}
    elif other is not None:
        raise ValueError("Unexpected value for 'other'")
    elif recompute:
        scale = sum(p for p in self._counts.values())
        self._n = sum(v for k, v in self._counts.items() if v > 0)
    else:
        scale = (self._n * (self._max * self._eps)) / sum(p for p in self._counts.values())
    self._max = 0
    self._min = float('inf')
    self._n -= 1
    self._counts = {i: 0 for i in range(self._n)}
    self._counts[self._n] = self._counts[self._n-1]
    self._max = self._counts[self._n] - scale * recompute
    self._min = self._counts[self._n] - scale * recompute
    return scale
```

