    except AttributeError as e:
        errors.append(f"The candidate does not implement a required method '{e}'.")

    # Check that the candidate defines all necessary attributes
    for attribute in iface.providedBy(candidate).attributes:
        if not hasattr(candidate, attribute):
            errors.append(f"The candidate does not define the attribute '{attribute}'.")

