def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check if explicit_meta is provided
    if explicit_mc:
        return explicit_mc

    # Initialize metaclass
    metaclass = type(None)

    # Check if bases are provided
    if bases:
        # Try to get the metaclass from the first base
        try:
            base_metaclass = bases[0].__metaclass__
            # Check if the base metaclass is not None
            if base_metaclass:
                metaclass = base_metaclass
        except AttributeError:
            pass

    # Custom error handling for metaclass not found
    if metaclass is None:
        raise ValueError("No metaclass can be determined from the provided bases or explicit metaclass.")

    return metaclass
