def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # Check the MIME type to determine if it's JSON or XRD
        if 'application/json' in document:
            # Parse the JSON document
            import json
            return json.loads(document)
        elif 'application/xhtml+xml' in document:
            # Parse the XHTML XML document
            from xml.etree.ElementTree import fromstring
            root = fromstring(document)
            data = {}
            for child in root:
                data[child.tag] = child.text
            return data
        else:
            # Handle other MIME types or raise an error
            raise ValueError("Unsupported MIME type")
    except json.JSONDecodeError:
        # Handle JSON parsing errors
        raise ValueError("Failed to parse JSON document")
    except Exception as e:
        # Handle other exceptions
        raise ValueError(f"An error occurred: {str(e)}")
