class IRValidator:
    @classmethod
    def validate_from_file(cls, yaml_file: Optional[str] = None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file provided for validation")

        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except yaml.YAMLError as exc:
            raise IRValidatorException(f'YAML error happened: {exc}')

        mandatory_fields = {
            "dataField": True,
            "anotherField": True
        }

        for field, required in mandatory_fields.items():
            if field not in data or not data[field]:
                raise IRValidatorException(f"Mandatory field '{field}' is missing in file")

        return data
