        'non_cli_arg2': int,
        'non_cli_arg3': float
    }

    # Iterate over each argument-value pair and cast if necessary
    converted_dict = {}
    for key, value in values_dict.items():
        expected_type = supported_types.get(key)
        if expected_type and not isinstance(value, expected_type):
            # Attempt to convert the value to the expected type
            try:
                converted_value = expected_type(value)
                converted_dict[key] = converted_value
            except ValueError:
                # If conversion fails, log the error and keep the original value
                self.logger.error(f"Failed to convert value for {key}: {value}")
                converted_dict[key] = value
