from os import path

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flatten_dict = {}
    if not path.exists(plugin_dir):
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist")
    for file_name in os.listdir(plugin_dir):
        file_path = path.join(plugin_dir, file_name)
        if os.path.isfile(file_path):
            if file_name.endswith(".json"):
                with open(file_path, 'r') as file:
                    spec = json.load(file)
                    for key, value in spec.items():
                        flatten_dict[key] = value
    return flatten_dict
